from agents.manager import run


def main() -> None:
    print("Spoonful Enterprise RAG System")
    print("Type 'exit' or 'quit' to stop.")

    while True:
        try:
            query = input("\nAsk a question: ").strip()
        except EOFError:
            print()
            break

        if query.lower() in {"exit", "quit"}:
            break

        if query:
            run(query)


if __name__ == "__main__":
    main()
